+                                      {
+                                          r.DocEntry,
+                                          r1.LineNum,
+                                          r1.ItemCode,
+                                          r1.DelivrdQty,
+                                          r1.Price,
+                                          m.ManSerNum,
+                                          m.ManBtchNum,
+                                          m.LastPurPrc,
+                                          r.SlpCode
